'use strict';
let language='en';
try{language=localStorage.getItem('element-language')==='zh'?'zh':'en';}catch{}
const L=(en,zh)=>language==='zh'?zh:en;
const elementName=e=>L(e.name,e.cn);
const families={'非金属':'Nonmetal','稀有气体':'Noble gas','碱金属':'Alkali metal','碱土金属':'Alkaline earth metal','类金属':'Metalloid','卤素':'Halogen','后过渡金属':'Post-transition metal','过渡金属':'Transition metal','镧系':'Lanthanide','锕系':'Actinide'};
const familyName=e=>L(families[e.family],e.family);
const compoundEnglish={
 ch4:{name:'Methane',geometry:'Tetrahedral · about 109.5°',description:'Carbon forms four single covalent bonds with hydrogen.',steps:[['Count valence electrons','Carbon contributes 4 electrons and four hydrogen atoms contribute 1 each: 8 in total.'],['Four C–H single bonds','Four shared electron pairs form four C–H bonds. Each line represents one pair.'],['Tetrahedral geometry','The four bonding pairs surround carbon in a tetrahedral arrangement. A Lewis drawing shows connections, not spatial angles.']]},
 co2:{name:'Carbon dioxide',geometry:'Linear · 180°',description:'Carbon forms a double bond with each oxygen atom. All three atoms lie on a straight line.',steps:[['Count valence electrons','Carbon contributes 4 electrons and each oxygen contributes 6: 16 in total.'],['Two pairs per double bond','Each double line in O=C=O represents two shared pairs. Each oxygen also has two lone pairs.'],['Shape and polarity','The C=O bonds are polar, but their dipoles cancel in the symmetric linear molecule. CO₂ is nonpolar.']]},
 h2o:{name:'Water',geometry:'Bent · about 104.5°',description:'Oxygen shares electrons with two hydrogen atoms and retains two lone pairs.',steps:[['Count valence electrons','Oxygen contributes 6 electrons and each hydrogen contributes 1: 8 in total.'],['Two bonds, two lone pairs','The two O–H bonds use 4 electrons. The remaining 4 form two lone pairs on oxygen.'],['Bent geometry','Bonding and lone pairs affect the arrangement around oxygen. Water is bent and polar.']]},
 nh3:{name:'Ammonia',geometry:'Trigonal pyramidal · about 107°',description:'Nitrogen forms three N–H bonds and retains one lone pair.',steps:[['Count valence electrons','Nitrogen contributes 5 electrons and three hydrogens contribute 1 each: 8 in total.'],['Three single bonds','Three pairs form the N–H bonds. The remaining pair is a lone pair on nitrogen.'],['Pyramidal geometry','The three hydrogens form the base of a pyramid. The lone pair makes the molecular shape different from trigonal planar.']]},
 hf:{name:'Hydrogen fluoride',geometry:'Diatomic',description:'Hydrogen and fluorine share one electron pair. Fluorine attracts the pair more strongly.',steps:[['Count valence electrons','Fluorine contributes 7 electrons and hydrogen contributes 1: 8 in total.'],['One shared pair','One pair forms the H–F bond. Fluorine retains three lone pairs.'],['Bond polarity','The higher electronegativity of fluorine draws bonding electron density toward it, making the bond polar.']]},
 hcl:{name:'Hydrogen chloride',geometry:'Diatomic',description:'Hydrogen chloride gas consists of HCl molecules. Its behavior in water is different.',steps:[['Count valence electrons','Chlorine contributes 7 electrons and hydrogen contributes 1: 8 in total.'],['One covalent bond','One shared pair forms the H–Cl bond. Chlorine retains three lone pairs.'],['Gas and solution','Gaseous HCl has a polar covalent bond. In water it predominantly forms hydrated hydrogen ions and chloride ions.']]},
 bf3:{name:'Boron trifluoride',geometry:'Trigonal planar · 120°',description:'Boron forms three B–F bonds. BF₃ is a common exception to the octet rule.',steps:[['Count valence electrons','Boron contributes 3 electrons and each fluorine contributes 7: 24 in total.'],['Bonds and lone pairs','Three B–F bonds use 6 electrons. The remaining electrons form lone pairs on fluorine.'],['An incomplete octet','In the simple Lewis structure, only 6 electrons surround boron. An octet is not required for every stable molecule.']]},
 sih4:{name:'Silane',geometry:'Tetrahedral · about 109.5°',description:'Silicon is in the same group as carbon and forms four single covalent bonds in silane.',steps:[['Group and valence electrons','Silicon and carbon each have 4 valence electrons. SiH₄ has 8 in total.'],['Four single bonds','Four shared pairs form four Si–H bonds.'],['Similar shape, different properties','Silane and methane have similar shapes, but their bond properties and reactivity differ.']]},
 ph3:{name:'Phosphine',geometry:'Trigonal pyramidal · about 93.5°',description:'Phosphorus forms three P–H bonds and retains one lone pair.',steps:[['Count valence electrons','Phosphorus contributes 5 electrons and three hydrogens contribute 3: 8 in total.'],['Distribute the pairs','Three pairs form single bonds and one remains as a lone pair.'],['Compare with ammonia','Both molecules are trigonal pyramidal, but their bond angles differ. A shape category does not give an exact angle.']]},
 h2s:{name:'Hydrogen sulfide',geometry:'Bent · about 92°',description:'Sulfur forms two S–H bonds and retains two lone pairs.',steps:[['Count valence electrons','Sulfur contributes 6 electrons and each hydrogen contributes 1: 8 in total.'],['Bonds and lone pairs','Two pairs form bonds and two remain as lone pairs on sulfur.'],['Compare with water','H₂S and water are both bent, but their bond angles and other properties differ.']]}
};
const ionicNames={lif:'Lithium fluoride',beo:'Beryllium oxide',nacl:'Sodium chloride',mgo:'Magnesium oxide',al2o3:'Aluminium oxide',kcl:'Potassium chloride',cacl2:'Calcium chloride'};
function localizedCompound(c){
 if(!c||language==='zh')return c;
 if(!c.ionic)return {...c,...compoundEnglish[c.id]};
 return {...c,name:ionicNames[c.id],geometry:'Ionic composition · not a molecule',description:`${ionicNames[c.id]} forms an extended crystal. The ionic model describes composition and charge balance; bonding can also have covalent character.`,steps:[['Ion charges',`${c.metal} is represented with charge +${c.positive}, and ${c.nonmetal} with charge −${c.negative}.`],['Balance the charges',`${c.formula} gives the simplest ratio with zero total charge.`],['An extended crystal','Electrostatic interactions between ions contribute to the crystal structure. The diagram shows ion types, not a complete unit cell or an isolated molecule.']]};
}
function behaviorText(e){
 const special={6:'Carbon commonly forms covalent bonds. The number of bonds depends on the molecule, not simply on the unpaired electrons of an isolated atom.',8:'Oxygen forms two covalent bonds and retains two lone pairs in water. Atomic configurations and molecular bonding use different models.',11:'Sodium occurs as Na⁺ in sodium chloride. Its ionic electron configuration differs from the neutral atom shown here.',14:'Silicon and carbon share a group. Equal valence electron counts do not imply equal bond strengths or reactivity.',17:'Chlorine can occur as Cl⁻ in ionic compounds or form covalent bonds.'};
 const en=e.predicted?'Experimental information is limited. Configurations and oxidation states may be theoretical and do not establish actual reactivity.':special[e.z]||(['d','f'].includes(e.block)?'Electrons in inner d or f subshells can participate in bonding. The outermost shell count alone is not the total valence electron count.':e.category==='noble'?'Closed shells usually correlate with low reactivity, but do not imply that compounds cannot exist.':'For main-group elements, outermost electrons provide a useful starting point for bonding. Actual properties depend on the compound.');
 return L(en,e.behavior);
}
function applyLanguage(){
 document.documentElement.lang=language==='zh'?'zh-CN':'en';
 document.title=L('Electron structure & chemical properties','电子结构与化学性质');
 for(const el of document.querySelectorAll('[data-en]'))el.textContent=el.dataset[language];
 for(const attribute of ['aria-label','placeholder','content'])for(const el of document.querySelectorAll(`[data-en-${attribute}]`))el.setAttribute(attribute,el.getAttribute(`data-${language}-${attribute}`));
 for(const el of document.querySelectorAll('[data-language]'))el.setAttribute('aria-pressed',String(el.dataset.language===language));
}
if(typeof module!=='undefined')module.exports={compoundEnglish,ionicNames,families};
